import {
  Group,
  PlaneGeometry,
  Mesh,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  TextureLoader,
  Vector2,
  DoubleSide,
  AdditiveBlending,
  Color,
} from 'three/webgpu';
import {
  uv,
  texture,
  positionLocal,
  normalLocal,
  uniform,
  float,
  vec2,
  vec3,
  vec4,
  mix,
  smoothstep,
  step,
  mul,
  add,
  sub,
  clamp,
  dot,
  normalize,
  reflect,
  positionWorldDirection,
  cameraPosition,
} from 'three/tsl';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Load textures (async) ---
  const depthTextureUniform = uniform(new TextureLoader().createTexture(1, 1)); // placeholder white
  let plateTexture = null;
  let depthMapTexture = null;

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    plateTexture = tex;
    tex.colorSpace = 'srgb';
    group.userData.plateMat.map = tex;
    group.userData.plateMat.needsUpdate = true;
  });

  ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
    depthMapTexture = tex;
    depthTextureUniform.value = tex;
    group.userData.plateMat.displacementMap = tex;
    group.userData.plateMat.needsUpdate = true;
  });

  // --- Plate material with displacement ---
  const plateGeometry = new PlaneGeometry(4.0, 2.5, 64, 64);
  const displacementAmplitude = 0.18;
  const displacementScale = float(displacementAmplitude);

  // TSL vertex displacement
  const depthSample = texture(depthTextureUniform, uv());
  const displacement = depthSample.r; // grayscale depth
  const displacedPosition = positionLocal.add(normalLocal.mul(displacement.mul(displacementScale)));

  const plateMat = new MeshStandardNodeMaterial({
    color: 0xffffff,
    roughness: 0.6,
    metalness: 0.2,
    side: DoubleSide,
    positionNode: displacedPosition,
  });
  group.userData.plateMat = plateMat;

  // Store reference for texture assignment
  plateMat.map = null;

  // --- Rim light via TSL (silhouette edge) ---
  const worldNormal = normalLocal.transformDirection(group.matrixWorld);
  const viewDir = positionWorldDirection.sub(cameraPosition).normalize();
  const rimFactor = float(1.0).sub(clamp(dot(worldNormal, viewDir), 0, 1));
  const rimIntensity = smoothstep(0.7, 1.0, rimFactor).mul(0.02);
  const rimColor = vec3(1.0, 1.0, 1.0); // key light white

  // Modify emission node
  const emissionNode = rimColor.mul(rimIntensity);
  plateMat.emissiveNode = emissionNode;
  plateMat.emissiveIntensity = 1.0;

  const plateMesh = new Mesh(plateGeometry, plateMat);
  plateMesh.position.z = 0;
  group.add(plateMesh);

  // --- Gradient scrim (bottom fade overlay) ---
  const scrimGeometry = new PlaneGeometry(4.0, 2.5);
  // TSL gradient: mix transparent at 0.45 to near-black at bottom
  const scrimUv = uv();
  const gradientFactor = smoothstep(0.45, 1.0, scrimUv.y);
  const scrimColor = vec4(0.043, 0.043, 0.063, 0.0); // #0b0b1000
  const scrimBottom = vec4(0.043, 0.043, 0.063, 0.921); // #0b0b10eb
  const scrimResult = mix(scrimColor, scrimBottom, gradientFactor);
  const scrimMat = new MeshBasicNodeMaterial({
    colorNode: scrimResult.rgb,
    opacityNode: scrimResult.a,
    transparent: true,
    depthWrite: false,
    renderOrder: 1,
  });
  const scrimMesh = new Mesh(scrimGeometry, scrimMat);
  scrimMesh.position.z = 0.01; // slightly in front
  group.add(scrimMesh);

  // --- Caption block (bottom-left) ---
  const captionGroup = new Group();
  captionGroup.position.set(-4.0 / 2 + 0.5, -2.5 / 2 + 0.5, 0.02); // bottom-left with 0.5 padding
  group.add(captionGroup);

  // Kickert: "NOVA ATELIER / GENEVA"
  const kickerText = ctx.fontAtlas.createText('NOVA ATELIER / GENEVA', {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 0.12 * 9, // 0.12em of 9px
  });
  kickerText.position.set(0, 0, 0);
  captionGroup.add(kickerText);

  // Headline: "Time, Machined."
  const headlineText = ctx.fontAtlas.createText('Time, Machined.', {
    fontSize: 34,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: -0.01 * 34,
  });
  headlineText.position.set(0, -34 * 1.1 - 0.25, 0); // line height 1.1 times fontSize + baseline rhythm (0.25 scene units)
  captionGroup.add(headlineText);

  // Accent hairline bar
  const barGeometry = new PlaneGeometry(0.75, 0.02);
  const barMat = new MeshBasicNodeMaterial({
    color: new Color(0xff2a38),
    emissiveNode: vec3(1, 0.165, 0.22),
    emissiveIntensity: 1.8,
  });
  const barMesh = new Mesh(barGeometry, barMat);
  barMesh.position.set(0, headlineText.position.y - 0.25 - 0.02, 0);
  captionGroup.add(barMesh);

  // Body: "Every case begins..."
  const bodyText = ctx.fontAtlas.createText('Every case begins as a single billet of 904L steel.', {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'left',
    maxWidthPx: 4.0 - 0.5 * 2, // constrained to plate width minus padding
  });
  bodyText.position.set(0, barMesh.position.y - 0.25 - 13 * 1.5, 0);
  captionGroup.add(bodyText);

  // Caption: "CALIBRE NA-01 / 72 HOUR RESERVE"
  const captionText = ctx.fontAtlas.createText('CALIBRE NA-01 / 72 HOUR RESERVE', {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 0.12 * 9,
  });
  captionText.position.set(0, bodyText.position.y - 13 * 1.5 - 0.25, 0);
  captionGroup.add(captionText);

  // --- Initial state for animations ---
  plateMat.opacity = 0;
  plateMat.transparent = true;
  captionGroup.children.forEach(child => {
    if (child.isMesh) {
      child.userData.originalY = child.position.y;
    }
  });
  captionGroup.position.y = captionGroup.position.y + 0.4; // start off

  // --- GSAP animations ---
  const tl = gsap.timeline({ paused: false });

  // Plate mount opacity
  tl.to(plateMat, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    onUpdate: () => {
      plateMat.transparent = true;
    },
  }, 0);

  // Caption block rise-in with delay
  tl.to(captionGroup.position, {
    y: captionGroup.position.y - 0.4, // back to original position
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)',
  }, 0.12);

  // Also animate children's original Y if needed (here just group)

  // --- Apply cinematic primitive: parallax-scroll ---
  const parallaxResult = ctx.primitives['parallax-scroll'](group, { intensity: 0.35 });

  // --- Setup event handlers (none specified) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tl.kill();
    if (parallaxResult && parallaxResult.cleanup) parallaxResult.cleanup();
    // Dispose geometries and materials
    [plateGeometry, scrimGeometry, barGeometry].forEach(geo => geo.dispose());
    [plateMat, scrimMat, barMat].forEach(mat => mat.dispose());
    // Dispose textures (if loaded)
    if (plateTexture) plateTexture.dispose();
    if (depthMapTexture) depthMapTexture.dispose();
    // Remove from parent
    if (group.parent) group.parent.remove(group);
  };

  return group;
}
